import { defineConfig } from 'vite'
import { resolve } from 'node:path'
import { LANGS } from './locales.mjs'

// Multi-language static site: pages are generated by scripts/pages.mjs before Vite runs.
// The legal pages read a copy of the app's Markdown files (site/legal, synced by scripts/pages.mjs).
const input = { main: resolve(import.meta.dirname, 'index.html') }
for (const lang of LANGS)
  for (const page of ['index', 'privacy', 'terms', 'licenses']) input[`${lang}-${page}`] = resolve(import.meta.dirname, lang, `${page}.html`)

export default defineConfig({
  build: { target: 'es2022', chunkSizeWarningLimit: 900, rollupOptions: { input } }
})
